// Lightweight pure-JS UUID v4 generator (no external crypto required)
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

function wrapText(text, maxChars = 16) {
  const words = text.trim().split(/\s+/);
  const lines = [];
  let cur = '';
  for (const w of words) {
    if ((cur + ' ' + w).trim().length <= maxChars) {
      cur = (cur + ' ' + w).trim();
    } else {
      if (cur) lines.push(cur);
      cur = w;
    }
  }
  if (cur) lines.push(cur);
  return lines;
}

function generateSvg(lines, width, height, baseFontSize, letterSpacing = 3) {
  const maxLineLen = Math.max(...lines.map(l => l.length)) || 1;
  const fontSize = Math.min(baseFontSize, Math.floor((width * 0.8) / maxLineLen));
  const lineHeight = fontSize * 1.25;
  const startY = (height / 2) - ((lines.length - 1) * lineHeight / 2);
  const tspans = lines.map((l, i) => `<tspan x="50%" y="${startY + (i * lineHeight)}">${l}</tspan>`).join('\n');
  return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg"><text text-anchor="middle" fill="#FFFFFF" font-family="Impact, Arial Black, sans-serif" font-size="${fontSize}" font-weight="bold" letter-spacing="${letterSpacing}">${tspans}</text></svg>`;
}

// TARGET PRODUCT CATALOG REGISTRY
const TARGET_PRODUCTS = [
  {
    name: 'T-Shirt',
    blueprint_id: 12,
    print_provider_id: 29,
    variant_id: 18102,
    price: 2500,
    width: 4000,
    height: 4800,
    maxChars: 16,
    baseFontSize: 320,
    placementY: 0.45
  },
  {
    name: 'Hoodie',
    blueprint_id: 380,
    print_provider_id: 29,
    variant_id: 45831,
    price: 4500,
    width: 4000,
    height: 4800,
    maxChars: 16,
    baseFontSize: 300,
    placementY: 0.50
  },
  {
    name: 'Tank Top',
    blueprint_id: 36,
    print_provider_id: 29,
    variant_id: 22101,
    price: 2200,
    width: 4000,
    height: 4800,
    maxChars: 14,
    baseFontSize: 300,
    placementY: 0.45
  },
  {
    name: 'Coffee Mug',
    blueprint_id: 68,
    print_provider_id: 1,
    variant_id: 17390,
    price: 1200,
    width: 2700,
    height: 1100,
    maxChars: 22,
    baseFontSize: 180,
    placementY: 0.50
  },
  {
    name: 'Phone Case',
    blueprint_id: 541,
    print_provider_id: 3,
    variant_id: 61201,
    price: 1800,
    width: 2000,
    height: 4000,
    maxChars: 12,
    baseFontSize: 240,
    placementY: 0.50
  }
];

const outputItems = [];

for (const item of $input.all()) {
  // Read slogan from 'Slogan Idea' or fallback fields
  const slogan = (item.json['Slogan Idea'] || item.json.Slogan || item.json.slogan || 'VIBEBLOOM').toUpperCase();

  // Use existing UUID or generate a new v4 UUID
  const sloganUuid = item.json.uuid || item.json.Slogan_id || generateUUID();

// --- NEW LOGIC: Filter products based on 'product_categories' ---
  const requestedCategories = item.json.product_categories || item.json.Product_categories;
  let filteredProducts = TARGET_PRODUCTS; // Default to all products

  // Check if there's actually data in the category field
  if (requestedCategories && requestedCategories.toString().trim() !== "") {

    // Convert whatever Google Sheets sent (Array, String, etc.) into one giant lowercase string
    const rawDataString = JSON.stringify(requestedCategories).toLowerCase();

    // Keep only the products whose name appears somewhere in that string
    filteredProducts = TARGET_PRODUCTS.filter(prod => {
      return rawDataString.includes(prod.name.toLowerCase());
    });
  }

  // Iterate over the dynamically filtered list instead of all products
  for (const prod of filteredProducts) {
    const lines = wrapText(slogan, prod.maxChars);
    const svgString = generateSvg(lines, prod.width, prod.height, prod.baseFontSize);
    const base64 = Buffer.from(svgString).toString('base64');
    const productSlug = prod.name.toLowerCase().replace(/\s+/g, '_');

    outputItems.push({
      json: {
        row_number: item.json.row_number,
        uuid: sloganUuid, 
        ...item.json,
        Slogan_id: sloganUuid,
        slogan: slogan,
        product_name: prod.name,
        blueprint_id: prod.blueprint_id,
        print_provider_id: prod.print_provider_id,

        // variant_id: prod.variant_id,
        // temporary hardcoding variant_id
        variant_id: 18102,
        price: prod.price,
        placement_y: prod.placementY,
        file_base64: base64,
        file_name: `${productSlug}_${sloganUuid.slice(0, 8)}.svg`
      }
    });
  }
}

return outputItems;

